import{_ as t,o as a,c as s,ae as n}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Secret Value Syntax","description":"","frontmatter":{"id":"3610135900","title":"Secret Value Syntax","state":"Approved","created":"2023-08-13T00:00:00.000Z","tags":["secret"],"category":"Platform"},"headers":[],"relativePath":"adrs/3610135900/README.md","filePath":"adrs/3610135900/README.md"}'),i={name:"adrs/3610135900/README.md"};function r(o,e,c,l,d,h){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="secret-value-syntax" tabindex="-1">Secret Value Syntax <a class="header-anchor" href="#secret-value-syntax" aria-label="Permalink to &quot;Secret Value Syntax&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The current ecosystem lacks a standardized format for secret values. This decentralization of secret format decisions leads to a situation where developers often define the format themselves. Such a disparate approach results in many developers either forgetting to set up scanning tools or being unable to utilize preconfigured scanning tools.</p><p>The lack of a consistent secret format hinders tools that would otherwise help guard against vulnerabilities and potential security risks. The changes in GitHub Authentication Token Formats, among other companies adding more meaningful prefixes to their secrets, highlight the need for a more standardized approach.</p><h3 id="decision-drivers" tabindex="-1">Decision Drivers: <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers:&quot;">​</a></h3><p><strong>Security:</strong> A standard format would enable more effective use of secret scanning tools, reducing the chances of leaks or unauthorized access.</p><p><strong>Consistency:</strong> A consistent secret format can streamline processes and reduce the chance of human error.</p><p><strong>Usability:</strong> Developers can more easily take advantage of preconfigured scanning tools with a standardized format.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>The agreed-upon structure will be similar to the URN syntax:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SECRET = &quot;secret:[NID]:[NSS]:[secret value]</span></span></code></pre></div><ul><li>&quot;secret:&quot; is the required case-sensitive scheme at the beginning.</li><li>NID (Namespace Identifier) defines the specific context or namespace. It is an optional case-sensitive and consist of only lower case alphanumeric characters and dashes value. Regex: <code>[a-z0-9-]</code>.</li><li>NSS (Namespace-Specific String) is unique within the specific namespace. It is an optional case-sensitive and consist of only lower case alphanumeric characters and dashes value. Regex: <code>[a-z0-9-]</code>.</li></ul><p>The secret regex value is:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>^secret:(?:[a-z0-9-]*):(?:[a-z0-9-]*):(.+)$</span></span></code></pre></div><p>For example, a Personal Access Token for GitHub could be in the format:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>secret:github:ghp:ghp_000000000000000000000000000000000000</span></span></code></pre></div><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/enterprise-cloud@latest/code-security/secret-scanning/defining-custom-patterns-for-secret-scanning" target="_blank" rel="noreferrer">https://docs.github.com/en/enterprise-cloud@latest/code-security/secret-scanning/defining-custom-patterns-for-secret-scanning</a></li><li><a href="https://github.blog/changelog/2021-03-31-authentication-token-format-updates-are-generally-available/" target="_blank" rel="noreferrer">https://github.blog/changelog/2021-03-31-authentication-token-format-updates-are-generally-available/</a></li><li><a href="https://docs.github.com/en/code-security/secret-scanning/about-secret-scanning" target="_blank" rel="noreferrer">https://docs.github.com/en/code-security/secret-scanning/about-secret-scanning</a></li><li><a href="https://support.discord.com/hc/en-us/articles/10069840290711" target="_blank" rel="noreferrer">https://support.discord.com/hc/en-us/articles/10069840290711</a></li></ul>',18)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
